import os
from typing import Dict, Any, Optional

import requests


PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"
DEFAULT_THRESHOLDS = {
    "TOXICITY": 0.8,
    "SEVERE_TOXICITY": 0.7,
    "INSULT": 0.8,
    "PROFANITY": 0.9,
    "THREAT": 0.6,
    "IDENTITY_ATTACK": 0.7,
    "SEXUALLY_EXPLICIT": 0.8,
    "FLIRTATION": 1.1,
}


class PerspectiveSafetyError(Exception):
    pass


def _normalize_thresholds(thresholds: Optional[Dict[str, float]]) -> Dict[str, float]:
    merged = dict(DEFAULT_THRESHOLDS)
    if thresholds:
        for key, value in thresholds.items():
            merged[key.upper()] = float(value)
    return merged


def apply_text_safety_thresholds(
    text: str,
    thresholds: Optional[Dict[str, float]] = None,
    language: Optional[str] = None,
    do_not_store: bool = True,
    timeout: float = 15.0,
) -> Dict[str, Any]:
    api_key = os.environ["PERSPECTIVE_API_KEY"]
    effective_thresholds = _normalize_thresholds(thresholds)

    requested_attributes = {attr: {} for attr in effective_thresholds.keys()}

    payload: Dict[str, Any] = {
        "comment": {"text": text},
        "requestedAttributes": requested_attributes,
        "doNotStore": do_not_store,
    }
    if language:
        payload["languages"] = [language]

    response = requests.post(
        PERSPECTIVE_API_URL,
        params={"key": api_key},
        json=payload,
        timeout=timeout,
    )

    if response.status_code != 200:
        raise PerspectiveSafetyError(
            f"Perspective API error {response.status_code}: {response.text}"
        )

    data = response.json()
    attribute_scores = data.get("attributeScores", {})

    scores: Dict[str, float] = {}
    violations: Dict[str, Dict[str, float]] = {}

    for attribute, threshold in effective_thresholds.items():
        attr_data = attribute_scores.get(attribute, {})
        summary_score = (
            attr_data.get("summaryScore", {}).get("value")
            if isinstance(attr_data, dict)
            else None
        )
        if summary_score is None:
            continue

        score = float(summary_score)
        scores[attribute] = score

        if score >= threshold:
            violations[attribute] = {
                "score": score,
                "threshold": threshold,
            }

    allowed = len(violations) == 0

    return {
        "provider": "Perspective API",
        "allowed": allowed,
        "scores": scores,
        "thresholds": effective_thresholds,
        "violations": violations,
        "text": text,
    }
